RECORD_ID
 , SESSION_ID 
 , NAME       
 , EMAIL      
 , IP_ADDRESS 
 , JOIN_TIME  
 , LEAVE_TIME 
) VALUES (
#{recordId}
 , #{sessionId} 
 , #{name}       
 , #{email}      
 , #{ipAddress} 
 , #{joinTime}  
 , #{leaveTime} 
)

mapper.update:
UPDATE ATTENDANCE_RECORD
SET
RECORD_ID = #{recordId}
 , SESSION_ID = #{sessionId} 
 , NAME = #{name}       
 , EMAIL = #{email}      
 , IP_ADDRESS = #{ipAddress} 
 , JOIN_TIME = #{joinTime}  
 , LEAVE_TIME = #{leaveTime} 
WHERE RECORD_ID = #{recordId}

mapper.select:
SELECT /* QueryID : com.demo.proworks.attendance.selectListAttendance */ record_id as recordId, session_id as sessionId, name, email, COALESCE(ip_address, '') as ipAddress, DATE_FORMAT(join_time, '%Y-%m-%d %H:%i:%s') as joinTime, CASE WHEN leave_time IS NOT NULL THEN DATE_FORMAT(leave_time, '%Y-%m-%d %H:%i:%s') ELSE '진행중' END as leaveTime, CASE WHEN leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, join_time, leave_time) ELSE '-' END as participationMinutes, CASE WHEN leave_time IS NULL THEN '참여중' ELSE '퇴장완료' END as status FROM ATTENDANCE_RECORD
AND session_id = #{scSessionId}
AND name LIKE CONCAT('%', #{scName}, '%')
AND email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(join_time) = #{scJoinTime}
ORDER BY join_time
ASC
DESC
LIMIT #{startRow}, #{pageSize}

SELECT /* QueryID : com.demo.proworks.attendance.selectListCountAttendance */ COUNT(*) FROM ATTENDANCE_RECORD WHERE 1=1
AND session_id = #{scSessionId}
AND name LIKE CONCAT('%', #{scName}, '%')
AND email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(join_time) = #{scJoinTime}
